<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>North & Nine | Modern Retail Essentials</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f6f3ee;
      --surface: #fffdf8;
      --surface-strong: #ffffff;
      --ink: #171512;
      --muted: #736b60;
      --line: #e7ded1;
      --accent: #c65d33;
      --accent-dark: #88401f;
      --sage: #6f806c;
      --gold: #d7a84d;
      --shadow: 0 24px 70px rgba(65, 46, 28, 0.12);
      --radius-xl: 34px;
      --radius-lg: 24px;
      --radius-md: 18px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(215, 168, 77, 0.18), transparent 34rem),
        linear-gradient(180deg, #fbf8f1 0%, var(--bg) 46%, #efe8dd 100%);
      color: var(--ink);
      min-height: 100vh;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button,
    input {
      font: inherit;
    }

    .page {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      padding: 28px 0;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      letter-spacing: -0.04em;
      font-size: 1.25rem;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      border-radius: 14px;
      background: var(--ink);
      color: #fff8ec;
      box-shadow: 0 14px 30px rgba(23, 21, 18, 0.18);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 28px;
      color: var(--muted);
      font-weight: 650;
      font-size: 0.95rem;
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .icon-button,
    .pill-button {
      border: 1px solid rgba(23, 21, 18, 0.12);
      background: rgba(255, 253, 248, 0.76);
      backdrop-filter: blur(16px);
      color: var(--ink);
      cursor: pointer;
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    .icon-button:hover,
    .pill-button:hover,
    .card:hover,
    .article-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow);
    }

    .icon-button {
      display: grid;
      place-items: center;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      font-size: 1.05rem;
    }

    .pill-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      min-height: 48px;
      padding: 0 22px;
      border-radius: 999px;
      font-weight: 750;
    }

    .pill-button.primary {
      background: var(--ink);
      color: #fffaf0;
      border-color: var(--ink);
    }

    .pill-button.accent {
      background: var(--accent);
      color: #fffaf0;
      border-color: var(--accent);
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.05fr) minmax(360px, 0.95fr);
      gap: 28px;
      align-items: stretch;
      min-height: 620px;
      padding: 24px 0 64px;
    }

    .hero-copy,
    .hero-showcase,
    .section-panel {
      border: 1px solid rgba(23, 21, 18, 0.08);
      background: rgba(255, 253, 248, 0.74);
      box-shadow: 0 30px 90px rgba(65, 46, 28, 0.1);
      backdrop-filter: blur(20px);
    }

    .hero-copy {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      border-radius: var(--radius-xl);
      padding: clamp(30px, 5vw, 62px);
      overflow: hidden;
      position: relative;
    }

    .hero-copy::after {
      content: "";
      position: absolute;
      right: -120px;
      bottom: -130px;
      width: 320px;
      height: 320px;
      border-radius: 50%;
      background: rgba(198, 93, 51, 0.13);
      pointer-events: none;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      width: fit-content;
      padding: 8px 14px;
      border: 1px solid rgba(198, 93, 51, 0.2);
      border-radius: 999px;
      color: var(--accent-dark);
      background: rgba(198, 93, 51, 0.08);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      max-width: 760px;
      margin: 26px 0 22px;
      font-size: clamp(3.2rem, 8vw, 6.8rem);
      line-height: 0.91;
      letter-spacing: -0.08em;
    }

    .hero-copy p {
      max-width: 610px;
      color: var(--muted);
      font-size: clamp(1.05rem, 2vw, 1.25rem);
      line-height: 1.65;
    }

    .hero-actions {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 14px;
      margin: 34px 0 42px;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      position: relative;
      z-index: 1;
    }

    .stat {
      padding: 18px;
      border: 1px solid var(--line);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.48);
    }

    .stat strong {
      display: block;
      font-size: 1.45rem;
      letter-spacing: -0.05em;
    }

    .stat span {
      display: block;
      margin-top: 6px;
      color: var(--muted);
      font-size: 0.88rem;
    }

    .hero-showcase {
      display: grid;
      grid-template-rows: 1fr auto;
      gap: 18px;
      border-radius: var(--radius-xl);
      padding: 18px;
      overflow: hidden;
    }

    .look-card {
      position: relative;
      min-height: 430px;
      border-radius: 28px;
      overflow: hidden;
      background:
        linear-gradient(150deg, rgba(23, 21, 18, 0.05), rgba(23, 21, 18, 0.44)),
        url("https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=80") center/cover;
    }

    .look-card-content {
      position: absolute;
      inset: auto 22px 22px 22px;
      padding: 22px;
      border-radius: 24px;
      background: rgba(255, 253, 248, 0.84);
      backdrop-filter: blur(18px);
    }

    .look-card-content h2 {
      margin-bottom: 8px;
      font-size: 2rem;
      letter-spacing: -0.06em;
    }

    .look-card-content p {
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .mini-row {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 18px;
    }

    .mini-card {
      padding: 20px;
      border-radius: 24px;
      background: var(--surface-strong);
      border: 1px solid var(--line);
    }

    .mini-card span {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .mini-card strong {
      display: block;
      margin-top: 8px;
      font-size: 1.35rem;
      letter-spacing: -0.05em;
    }

    section {
      padding: 38px 0;
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 22px;
      margin-bottom: 22px;
    }

    .section-heading h2 {
      margin-bottom: 6px;
      font-size: clamp(2rem, 4vw, 3.35rem);
      letter-spacing: -0.07em;
    }

    .section-heading p {
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.6;
      max-width: 560px;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .card,
    .article-card,
    .deal-banner {
      border: 1px solid var(--line);
      background: var(--surface);
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .card {
      border-radius: 26px;
      overflow: hidden;
    }

    .product-media {
      display: grid;
      place-items: center;
      min-height: 245px;
      margin: 10px;
      border-radius: 22px;
      background: var(--product-bg);
      position: relative;
      overflow: hidden;
    }

    .product-media::before {
      content: "";
      position: absolute;
      width: 130px;
      height: 130px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.45);
      filter: blur(2px);
    }

    .product-emoji {
      position: relative;
      font-size: 5.2rem;
      filter: drop-shadow(0 18px 22px rgba(23, 21, 18, 0.16));
    }

    .badge {
      position: absolute;
      top: 14px;
      left: 14px;
      padding: 7px 11px;
      border-radius: 999px;
      background: rgba(255, 253, 248, 0.84);
      color: var(--accent-dark);
      font-size: 0.74rem;
      font-weight: 850;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .product-info {
      padding: 8px 20px 22px;
    }

    .product-topline {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      color: var(--muted);
      font-size: 0.85rem;
      font-weight: 650;
    }

    .product-info h3 {
      margin: 12px 0 12px;
      font-size: 1.22rem;
      letter-spacing: -0.04em;
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      font-weight: 850;
    }

    .add-button {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border: 0;
      border-radius: 50%;
      background: var(--ink);
      color: #fffaf0;
      cursor: pointer;
    }

    .deals-layout {
      display: grid;
      grid-template-columns: 1.18fr 0.82fr;
      gap: 18px;
    }

    .deal-banner {
      display: grid;
      grid-template-columns: 1fr 0.78fr;
      min-height: 360px;
      border-radius: var(--radius-xl);
      overflow: hidden;
      background:
        linear-gradient(135deg, rgba(23, 21, 18, 0.92), rgba(74, 49, 32, 0.88)),
        radial-gradient(circle at 90% 10%, rgba(215, 168, 77, 0.5), transparent 24rem);
      color: #fffaf0;
    }

    .deal-copy {
      padding: clamp(28px, 4vw, 48px);
    }

    .deal-copy h2 {
      margin: 18px 0 14px;
      font-size: clamp(2.2rem, 5vw, 4.7rem);
      line-height: 0.95;
      letter-spacing: -0.08em;
    }

    .deal-copy p {
      color: rgba(255, 250, 240, 0.74);
      line-height: 1.65;
      max-width: 470px;
    }

    .timer {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin: 30px 0;
    }

    .timer-box {
      min-width: 76px;
      padding: 13px 16px;
      border: 1px solid rgba(255, 250, 240, 0.16);
      border-radius: 18px;
      background: rgba(255, 250, 240, 0.08);
      text-align: center;
    }

    .timer-box strong {
      display: block;
      font-size: 1.3rem;
    }

    .timer-box span {
      color: rgba(255, 250, 240, 0.62);
      font-size: 0.74rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .deal-art {
      min-height: 100%;
      background:
        linear-gradient(180deg, transparent, rgba(23, 21, 18, 0.34)),
        url("https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=900&q=80") center/cover;
    }

    .deal-stack {
      display: grid;
      gap: 18px;
    }

    .deal-tile {
      padding: 28px;
      border-radius: 28px;
      background: var(--surface);
      border: 1px solid var(--line);
    }

    .deal-tile strong {
      display: block;
      margin-bottom: 8px;
      font-size: 2rem;
      letter-spacing: -0.06em;
    }

    .deal-tile p {
      margin-bottom: 20px;
      color: var(--muted);
      line-height: 1.55;
    }

    .deal-tile.sage {
      background: #e6eadf;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr 0.9fr;
      gap: 18px;
    }

    .article-card {
      min-height: 410px;
      border-radius: 28px;
      overflow: hidden;
    }

    .article-image {
      min-height: 245px;
      background: var(--article-image) center/cover;
    }

    .article-content {
      padding: 24px;
    }

    .article-kicker {
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .article-content h3 {
      margin: 12px 0 10px;
      font-size: clamp(1.35rem, 2vw, 1.9rem);
      line-height: 1.08;
      letter-spacing: -0.05em;
    }

    .article-content p {
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.58;
    }

    .newsletter {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 24px;
      align-items: center;
      margin: 42px 0 58px;
      padding: clamp(26px, 5vw, 46px);
      border-radius: var(--radius-xl);
      background: var(--ink);
      color: #fffaf0;
      overflow: hidden;
      position: relative;
    }

    .newsletter::after {
      content: "";
      position: absolute;
      inset: -120px -80px auto auto;
      width: 280px;
      height: 280px;
      border-radius: 50%;
      background: rgba(215, 168, 77, 0.28);
    }

    .newsletter h2 {
      margin-bottom: 10px;
      font-size: clamp(2rem, 4vw, 3.2rem);
      letter-spacing: -0.07em;
    }

    .newsletter p {
      margin-bottom: 0;
      color: rgba(255, 250, 240, 0.7);
      line-height: 1.6;
      max-width: 650px;
    }

    .signup {
      display: flex;
      gap: 10px;
      padding: 8px;
      border-radius: 999px;
      background: rgba(255, 250, 240, 0.1);
      border: 1px solid rgba(255, 250, 240, 0.16);
      position: relative;
      z-index: 1;
    }

    .signup input {
      min-width: min(320px, 42vw);
      border: 0;
      outline: 0;
      background: transparent;
      color: #fffaf0;
      padding: 0 12px;
    }

    .signup input::placeholder {
      color: rgba(255, 250, 240, 0.52);
    }

    footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 24px 0 42px;
      color: var(--muted);
      font-size: 0.92rem;
    }

    @media (max-width: 980px) {
      .nav-links {
        display: none;
      }

      .hero,
      .deals-layout,
      .deal-banner,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .article-card:first-child {
        grid-column: 1 / -1;
      }

      .deal-art {
        min-height: 280px;
      }
    }

    @media (max-width: 640px) {
      .page {
        width: min(100% - 22px, 1180px);
      }

      .nav {
        padding: 18px 0;
      }

      .nav-actions .pill-button {
        display: none;
      }

      .hero {
        grid-template-columns: 1fr;
        min-height: unset;
        padding-top: 8px;
      }

      .stats,
      .mini-row,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .section-heading {
        align-items: start;
        flex-direction: column;
      }

      .signup {
        align-items: stretch;
        flex-direction: column;
        border-radius: 24px;
      }

      .signup input {
        min-width: 100%;
        min-height: 44px;
      }

      footer {
        align-items: start;
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const products = [
      {
        name: "CloudKnit Lounge Set",
        category: "New essentials",
        price: "$128",
        rating: "4.9",
        badge: "Just in",
        emoji: "🧥",
        bg: "linear-gradient(135deg, #efe2d0, #d9c2a5)"
      },
      {
        name: "Daily Carry Tote",
        category: "Accessories",
        price: "$86",
        rating: "4.8",
        badge: "Bestseller",
        emoji: "👜",
        bg: "linear-gradient(135deg, #e5e8dd, #bcc8ad)"
      },
      {
        name: "Ribbed Weekender",
        category: "Travel edit",
        price: "$74",
        rating: "4.7",
        badge: "Low stock",
        emoji: "👟",
        bg: "linear-gradient(135deg, #f4ddcb, #d99b76)"
      },
      {
        name: "Studio Ceramic Set",
        category: "Home",
        price: "$58",
        rating: "4.9",
        badge: "Gift pick",
        emoji: "☕",
        bg: "linear-gradient(135deg, #ece8dc, #cabf9d)"
      }
    ];

    const articles = [
      {
        kicker: "The spring brief",
        title: "Build a 12-piece wardrobe that works from desk to dinner.",
        excerpt: "Our editors map the silhouettes, textures, and colors worth refreshing this season.",
        image: "url('https://images.unsplash.com/photo-1485125639709-a60c3a500bf1?auto=format&fit=crop&w=900&q=80')"
      },
      {
        kicker: "At home",
        title: "Small upgrades that make everyday rituals feel considered.",
        excerpt: "Warm lighting, tactile ceramics, and storage pieces that keep counters calm.",
        image: "url('https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=800&q=80')"
      },
      {
        kicker: "Buying better",
        title: "How we choose materials for longevity and lower impact.",
        excerpt: "A look inside our fabric standards, repair program, and supplier scorecards.",
        image: "url('https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=800&q=80')"
      }
    ];

    const html = String.raw;

    function Header() {
      return html`
        <header class="nav" aria-label="Main navigation">
          <a class="brand" href="#" aria-label="North and Nine home">
            <span class="brand-mark">N9</span>
            <span>North & Nine</span>
          </a>
          <nav class="nav-links" aria-label="Primary">
            <a href="#featured">Featured</a>
            <a href="#deals">Deals</a>
            <a href="#editorial">Editorial</a>
            <a href="#newsletter">Members</a>
          </nav>
          <div class="nav-actions">
            <button class="icon-button" type="button" aria-label="Search">⌕</button>
            <button class="icon-button" type="button" aria-label="Shopping bag">□</button>
            <a class="pill-button" href="#featured">Shop now</a>
          </div>
        </header>
      `;
    }

    function Hero() {
      return html`
        <section class="hero" aria-labelledby="hero-title">
          <div class="hero-copy">
            <div>
              <span class="eyebrow">New season edit</span>
              <h1 id="hero-title">Retail therapy, refined.</h1>
              <p>
                Discover considered fashion, home objects, and everyday upgrades selected
                for effortless routines and modern living.
              </p>
              <div class="hero-actions">
                <a class="pill-button primary" href="#featured">Shop featured</a>
                <a class="pill-button" href="#editorial">Read the edit</a>
              </div>
            </div>
            <div class="stats" aria-label="Store highlights">
              <div class="stat"><strong>240+</strong><span>new arrivals weekly</span></div>
              <div class="stat"><strong>48h</strong><span>carbon-aware dispatch</span></div>
              <div class="stat"><strong>4.9</strong><span>average product rating</span></div>
            </div>
          </div>
          <aside class="hero-showcase" aria-label="Featured look">
            <div class="look-card">
              <div class="look-card-content">
                <h2>The city escape capsule</h2>
                <p>Layerable textures, compact carryalls, and polished comfort for weekends away.</p>
              </div>
            </div>
            <div class="mini-row">
              <div class="mini-card"><span>Members save</span><strong>15% today</strong></div>
              <div class="mini-card"><span>Free shipping</span><strong>Over $75</strong></div>
            </div>
          </aside>
        </section>
      `;
    }

    function SectionHeading({ eyebrow, title, copy, action }) {
      return html`
        <div class="section-heading">
          <div>
            <span class="eyebrow">${eyebrow}</span>
            <h2>${title}</h2>
            <p>${copy}</p>
          </div>
          ${action ? `<a class="pill-button" href="${action.href}">${action.label}</a>` : ""}
        </div>
      `;
    }

    function ProductCard(product) {
      return html`
        <article class="card">
          <div class="product-media" style="--product-bg: ${product.bg}">
            <span class="badge">${product.badge}</span>
            <span class="product-emoji" aria-hidden="true">${product.emoji}</span>
          </div>
          <div class="product-info">
            <div class="product-topline">
              <span>${product.category}</span>
              <span>★ ${product.rating}</span>
            </div>
            <h3>${product.name}</h3>
            <div class="price-row">
              <span>${product.price}</span>
              <button class="add-button" type="button" aria-label="Add ${product.name} to cart">+</button>
            </div>
          </div>
        </article>
      `;
    }

    function FeaturedProducts() {
      return html`
        <section id="featured" aria-labelledby="featured-title">
          ${SectionHeading({
            eyebrow: "Featured products",
            title: "Fresh drops with staying power.",
            copy: "Customer-loved arrivals chosen for quality, versatility, and a quietly elevated finish.",
            action: { href: "#", label: "View all" }
          }).replace("<h2>", '<h2 id="featured-title">')}
          <div class="product-grid">
            ${products.map(ProductCard).join("")}
          </div>
        </section>
      `;
    }

    function Deals() {
